import requests
from bs4 import BeautifulSoup

def web_recon(host, port=80, use_ssl=False, timeout=5):
    scheme = 'https' if use_ssl else 'http'
    url = f"{scheme}://{host}:{port}"
    try:
        resp = requests.get(url, timeout=timeout, allow_redirects=True)
        resp.raise_for_status()
        soup = BeautifulSoup(resp.text, 'html.parser')
        title = soup.title.string.strip() if soup.title else 'No title'
        headers = dict(resp.headers)
        return {
            'status_code': resp.status_code,
            'title': title,
            'server': headers.get('Server', 'Unknown'),
            'content_type': headers.get('Content-Type', ''),
            'headers': headers
        }
    except Exception as e:
        return {'error': str(e)}

def web_recon(host, port=80, use_ssl=False, timeout=5, ignore_ssl=False):
    scheme = 'https' if use_ssl else 'http'
    url = f"{scheme}://{host}:{port}"
    try:
        verify = not ignore_ssl
        resp = requests.get(url, timeout=timeout, verify=verify)
        # ... rest
    except requests.exceptions.SSLError as e:
        if ignore_ssl:
            return web_recon(host, port, use_ssl, timeout, ignore_ssl=False)  # fallback?
        else:
            return {'error': f'SSL Error: {e}'}
    except Exception as e:
        return {'error': str(e)}
